// Set week variables in both English and Arabic
const now = new Date();

// Arabic month names
const arabicMonths = [
  'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
  'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
];

// Convert to Arabic numerals
function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}

// Get week number
function getWeekNumber(d) {
  d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  return weekNo;
}

// Get week start and end dates
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 6); // Start of the week (Sunday)
const weekEnd = now;

const year = now.getFullYear();
const weekNumber = getWeekNumber(now);

const weekStartArabic = `${toArabicNumerals(weekStart.getDate())} ${arabicMonths[weekStart.getMonth()]}`;
const weekEndArabic = `${toArabicNumerals(weekEnd.getDate())} ${arabicMonths[weekEnd.getMonth()]} ${toArabicNumerals(year)}`;

const fileName = `تقرير_أسبوعي_${year}-W${String(weekNumber).padStart(2, '0')}.docx`;

return {
  json: {
    week_start_arabic: weekStartArabic,
    week_end_arabic: weekEndArabic,
    week_start_english: weekStart.toISOString().split('T')[0],
    week_end_english: weekEnd.toISOString().split('T')[0],
    year: year,
    week_number: weekNumber,
    week_number_arabic: toArabicNumerals(weekNumber),
    file_name: fileName,
    report_title: `التقرير الأسبوعي للرصد الجنائي - الأسبوع ${toArabicNumerals(weekNumber)} - ${year}`,
    search_recency: 'week'
  }
};

// Merge all academic research results
const criminology = $('Scholar - Criminology Research').item?.json?.organic_results || [];
const jcj = $('Scholar - Journal of Criminal Justice').item?.json?.organic_results || [];
const prevention = $('Scholar - Crime Prevention').item?.json?.organic_results || [];
const cybercrime = $('Scholar - Cybercrime').item?.json?.organic_results || [];
const financial = $('Scholar - Financial Crime').item?.json?.organic_results || [];

const allStudies = [...criminology, ...jcj, ...prevention, ...cybercrime, ...financial];

// Deduplicate by title
const seen = new Set();
const uniqueStudies = allStudies.filter(study => {
  const key = study.title?.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

// Format studies for Perplexity analysis
const formattedStudies = uniqueStudies.slice(0, 15).map((s, i) => ({
  index: i + 1,
  title: s.title,
  authors: s.publication_info?.authors || 'Unknown',
  source: s.publication_info?.summary || s.source,
  link: s.link,
  snippet: s.snippet,
  cited_by: s.inline_links?.cited_by?.total || 0
}));

return {
  json: {
    studies_count: formattedStudies.length,
    studies: formattedStudies
  }
};

// Merge international reports
const unodc = $('SERP - UNODC Reports').item?.json?.organic_results || [];
const interpol = $('SERP - INTERPOL Statistics').item?.json?.organic_results || [];
const fbi = $('SERP - FBI UCR').item?.json?.organic_results || [];

return {
  json: {
    unodc_reports: unodc.slice(0, 5).map(r => ({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    })),
    interpol_reports: interpol.slice(0, 5).map(r => ({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    })),
    fbi_reports: fbi.slice(0, 5).map(r => ({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    }))
  }
};

// Merge best practices results
const investigative = $('SERP - Investigative Techniques').item?.json?.organic_results || [];
const community = $('SERP - Community Prevention').item?.json?.organic_results || [];

return {
  json: {
    investigative_techniques: investigative.slice(0, 5).map(r => ({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    })),
    community_approaches: community.slice(0, 5).map(r => ({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    }))
  }
};

