// Collect all sources for reference database
const studies = $('Merge Academic Research').item?.json?.studies || [];
const intlReports = $('Merge International Reports').item?.json || {};
const bestPractices = $('Merge Best Practices').item?.json || {};

const references = [];

// Process academic studies
studies.forEach(study => {
  if (study.link) {
    references.push({
      title: study.title,
      url: study.link,
      source_type: 'academic',
      source_name: study.source,
      authors: study.authors,
      publication_date: new Date().toISOString().split('T')[0],
      crime_type: ['other'],
      region: ['Global'],
      geographical_scope: 'international',
      relevance_score: study.cited_by > 10 ? 5 : study.cited_by > 5 ? 4 : 3
    });
  }
});

// Process international reports
['unodc_reports', 'interpol_reports', 'fbi_reports'].forEach(key => {
  const reports = intlReports[key] || [];
  reports.forEach(report => {
    if (report.link) {
      references.push({
        title: report.title,
        url: report.link,
        source_type: 'international_org',
        source_name: key.replace('_reports', '').toUpperCase(),
        publication_date: new Date().toISOString().split('T')[0],
        crime_type: ['other'],
        region: ['Global'],
        geographical_scope: 'international'
      });
    }
  });
});

// Process best practices
['investigative_techniques', 'community_approaches'].forEach(key => {
  const items = bestPractices[key] || [];
  items.forEach(item => {
    if (item.link) {
      references.push({
        title: item.title,
        url: item.link,
        source_type: 'governmental',
        publication_date: new Date().toISOString().split('T')[0],
        crime_type: ['other'],
        region: ['Global'],
        geographical_scope: 'international'
      });
    }
  });
});

return {
  json: {
    operation: 'ADD_BATCH_REFERENCES',
    references: references.slice(0, 40)
  }
};

// Generate the complete Arabic weekly report
const weekVars = $('Set Week Variables').item.json;
const studiesSummary = $('Perplexity - Summarize Studies').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const globalPatterns = $('Perplexity - Global Patterns').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const uaeComparison = $('Perplexity - UAE Comparison').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const bestPractices = $('Perplexity - Best Practices').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const executiveSummary = $('Perplexity - Executive Summary').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';

// Collect citations
const studiesCitations = $('Perplexity - Summarize Studies').item?.json?.citations || [];
const globalCitations = $('Perplexity - Global Patterns').item?.json?.citations || [];
const uaeCitations = $('Perplexity - UAE Comparison').item?.json?.citations || [];
const practicesCitations = $('Perplexity - Best Practices').item?.json?.citations || [];

const allCitations = [...new Set([...studiesCitations, ...globalCitations, ...uaeCitations, ...practicesCitations])];

let academicRefs = '';
let governmentalRefs = '';
let intlOrgRefs = '';

allCitations.forEach((cite, i) => {
  if (cite.includes('scholar') || cite.includes('journal') || cite.includes('research')) {
    academicRefs += `${i + 1}. ${cite}\n`;
  } else if (cite.includes('gov') || cite.includes('fbi')) {
    governmentalRefs += `${i + 1}. ${cite}\n`;
  } else {
    intlOrgRefs += `${i + 1}. ${cite}\n`;
  }
});

const studiesCount = $('Merge Academic Research').item?.json?.studies_count || 0;

const report = `
═══════════════════════════════════════════════════════════════
التقرير الأسبوعي للرصد الجنائي والأمني
───────────────────────────────────────────────────────────────
الأسبوع المنتهي في: ${weekVars.week_end_arabic}
الأسبوع رقم: ${weekVars.week_number_arabic} من عام ${weekVars.year}
وقت الإصدار: ٠٧:٠٠ صباحاً - الجمعة
═══════════════════════════════════════════════════════════════

المحتويات:
─────────
١. ملخص تنفيذي
٢. ملخصات الأبحاث والدراسات الجديدة
٣. تحليل الأنماط الجنائية العالمية
٤. مقارنة السياق الإماراتي
٥. أفضل الممارسات الدولية
٦. المراجع والمصادر

═══════════════════════════════════════════════════════════════
١. الملخص التنفيذي
═══════════════════════════════════════════════════════════════
${executiveSummary}

═══════════════════════════════════════════════════════════════
٢. ملخصات الأبحاث والدراسات الجديدة
═══════════════════════════════════════════════════════════════
عدد الدراسات المراجعة هذا الأسبوع: ${studiesCount}
(ملخص لا يتجاوز ٣٠٠ كلمة لكل دراسة)

${studiesSummary}

═══════════════════════════════════════════════════════════════
٣. تحليل الأنماط الجنائية العالمية
═══════════════════════════════════════════════════════════════
${globalPatterns}

═══════════════════════════════════════════════════════════════
٤. مقارنة السياق الإماراتي
═══════════════════════════════════════════════════════════════
${uaeComparison}

═══════════════════════════════════════════════════════════════
٥. أفضل الممارسات الدولية
═══════════════════════════════════════════════════════════════
${bestPractices}

═══════════════════════════════════════════════════════════════
٦. المراجع والمصادر
═══════════════════════════════════════════════════════════════
تصنيف المراجع:

أ. المصادر الأكاديمية:
${academicRefs || 'متوفرة في قاعدة البيانات المرجعية'}

ب. المصادر الحكومية:
${governmentalRefs || 'متوفرة في قاعدة البيانات المرجعية'}

ج. مصادر المنظمات الدولية:
${intlOrgRefs || 'متوفرة في قاعدة البيانات المرجعية'}

───────────────────────────────────────────────────────────────
نهاية التقرير
تم إعداد هذا التقرير آلياً بواسطة نظام الرصد الجنائي
───────────────────────────────────────────────────────────────
`;

return {
  json: {
    report_content: report,
    report_title: weekVars.report_title,
    file_name: weekVars.file_name,
    week_end: weekVars.week_end_english
  }
};

